"""Render discovered tags as a Telegraf `[[inputs.opcua]]` block.

Pure: takes a list of TagNode, returns text. No network, no files.
"""

from ..model import TagNode

# Telegraf reads these as strings even though they are numbers/enums.
_HEADER = """\
# Generated by opcua-tagmap. {count} node(s) from {endpoint}
[[inputs.opcua]]
  name = "{name}"
  endpoint = "{endpoint}"
  connect_timeout = "10s"
  request_timeout = "5s"
  security_policy = "None"
  security_mode = "None"
  auth_method = "Anonymous"
"""

_NODE = """
  [[inputs.opcua.nodes]]
    name = "{name}"
    namespace = "{namespace}"
    identifier_type = "{identifier_type}"
    identifier = "{identifier}"
"""


def _toml_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace('"', '\\"')


def render(tags: list[TagNode], endpoint: str, name: str = "opcua") -> str:
    """Build a complete, paste-able Telegraf input block."""
    out = [_HEADER.format(count=len(tags), endpoint=_toml_escape(endpoint),
                          name=_toml_escape(name))]

    for tag in tags:
        out.append(_NODE.format(
            name=_toml_escape(tag.display_name),
            namespace=tag.namespace,
            identifier_type=tag.identifier_type,
            identifier=_toml_escape(tag.identifier),
        ))

    return "".join(out)
